{
  "decision_framework": {
    "summary": "Choosing between an immutable market and an updatable market on lending platforms like Onlend comes down to the tradeoff between trust minimization (code-is-law immutability) and active risk adaptability (governance/curator flexibility).",
    "key_evaluation_factors": [
      {
        "factor": "Governance and Smart Contract Risk",
        "immutable_preference": "Choose immutable if you require zero governance intervention, trust-minimized architecture, and immunity to rug pulls, malicious parameter tampering, or DAO governance fatigue. Similar to Morpho Blue or Ajna Finance, once deployed, the parameters cannot be altered.",
        "updatable_preference": "Choose updatable if you accept protocol or multi-sig admin oversight in exchange for active monitoring and protection against unforeseen systemic shocks, similar to Aave v3 or Compound v3."
      },
      {
        "factor": "Asset Volatility and Maturity",
        "immutable_preference": "Best suited for mature, highly liquid base assets (e.g., WETH, WBTC, USDC) or hard-pegged pairs where liquidity dynamics, volatility, and market depth are well understood and unlikely to experience structural shifts.",
        "updatable_preference": "Ideal for newer, volatile, or rapidly evolving tokens (e.g., restaking tokens like LRTs, yield-bearing assets, or low-cap DeFi tokens) where Loan-to-Value (LLTV) thresholds, liquidation bonuses, and borrow caps must be tuned as liquidity deepens or thins."
      },
      {
        "factor": "Oracle Reliance and Feed Lifecycle",
        "immutable_preference": "Requires 100% confidence in the oracle implementation (e.g., fixed Chainlink or Uniswap TWAP feed) because the oracle contract address and logic can never be migrated or swapped out if the feed deprecates or fails.",
        "updatable_preference": "Necessary if the underlying collateral relies on oracles that may deprecate, undergo upgrades, or require switching fallback providers (e.g., toggling between Chainlink, Pyth Network, and RedStone)."
      },
      {
        "factor": "Operational Overhead and Liquidity Migration",
        "immutable_preference": "Zero operational maintenance costs. However, if market parameters become obsolete or uncompetitive, the only solution is for users to manually withdraw and migrate liquidity to a newly deployed market.",
        "updatable_preference": "Requires continuous monitoring and risk curation (often conducted by specialized risk curators like Gauntlet or Chaos Labs), but saves liquidity providers and borrowers from having to repeatedly migrate positions when interest rate models or caps need adjusting."
      }
    ]
